/**
 * Cloudflare Pages Functions Middleware
 * Serves the markdown face of the site to agents (Accept: text/markdown, /<page>.md,
 * or the legacy ?agent=true), and renders guestbook entries into /guestbook for
 * readers without JS
 *
 * MARKDOWN is generated by scripts/prebuild.ts from siteData.ts
 */

import MARKDOWN from './_generated/markdown.json';

// --- MARKDOWN FOR AGENTS ---

// Legacy ?agent=true&content=<section> URLs land on the markdown page that covers them
const LEGACY_CONTENT = {
  profile: '/',
  contact: '/',
  resume: '/resume',
  skills: '/resume',
  projects: '/lab',
};

function normalizePath(pathname) {
  const path = pathname.replace(/\/+$/, '') || '/';
  return path === '/index' ? '/' : path;
}

function markdownUrl(page) {
  return `${page === '/' ? '/index' : page}.md`;
}

// True when Accept ranks text/markdown at least as high as text/html. Browsers never ask for it.
function prefersMarkdown(accept) {
  if (!accept) return false;
  let markdown = 0;
  let html = 0;
  for (const part of accept.split(',')) {
    const [type, ...params] = part.split(';').map((p) => p.trim().toLowerCase());
    const qParam = params.find((p) => p.startsWith('q='));
    const q = qParam ? parseFloat(qParam.slice(2)) : 1;
    if (!Number.isFinite(q)) continue;
    if (type === 'text/markdown') markdown = Math.max(markdown, q);
    if (type === 'text/html') html = Math.max(html, q);
  }
  return markdown > 0 && markdown >= html;
}

// The markdown page this request asks for, or null for the normal HTML site
function markdownPageFor(request, url) {
  const path = normalizePath(url.pathname);
  if (path.endsWith('.md')) {
    const page = normalizePath(path.slice(0, -3));
    return page in MARKDOWN ? page : null;
  }
  if (!(path in MARKDOWN)) return null;
  if (url.searchParams.get('agent') === 'true') {
    return LEGACY_CONTENT[url.searchParams.get('content')] || path;
  }
  return prefersMarkdown(request.headers.get('Accept')) ? path : null;
}

async function serveMarkdown(page) {
  let body = MARKDOWN[page];
  if (page === '/guestbook') {
    body = body.replace(GUESTBOOK_ENTRIES_MARKER, await renderGuestbookEntriesMarkdown());
  }
  return new Response(body, {
    headers: {
      'Content-Type': 'text/markdown; charset=utf-8',
      Vary: 'Accept',
      Link: `<https://brysontang.com${page === '/' ? '/' : page}>; rel="canonical"`,
      'Cache-Control': page === '/guestbook' ? 'no-cache' : 'public, max-age=300',
    },
  });
}

// Point HTML readers at the markdown version, and keep caches from mixing the two.
// The home page also points at the API catalog (RFC 9727).
function withMarkdownHeaders(response, page) {
  const headers = new Headers(response.headers);
  headers.append('Vary', 'Accept');
  headers.append('Link', `<${markdownUrl(page)}>; rel="alternate"; type="text/markdown"`);
  if (page === '/') {
    headers.append('Link', '</.well-known/api-catalog>; rel="api-catalog"');
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

// --- GUESTBOOK SERVER-SIDE RENDERING ---
// Entries used to load only via JS, so fetchers that don't run JS saw
// "Loading entries...". Bake them into the HTML and the markdown here instead.

const GUESTBOOK_API = 'https://api.brysontang.com/api/guestbook';
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

// Keep in sync with GUESTBOOK_ENTRIES_MARKER in scripts/prebuild.ts
const GUESTBOOK_ENTRIES_MARKER = '<!-- guestbook-entries -->';

// Messages for ?error=<code> after a no-JS form post (codes come from the API worker)
const GUESTBOOK_ERRORS = {
  rate: 'You already signed in the last hour. Try again later.',
  missing: 'Please fill in both your name and a message.',
  placeholder: 'Please sign with your own name and message, not the example text.',
  name: 'Name too long (max 50 characters).',
  message: 'Message too long (max 500 characters).',
  origin: 'That submission did not come from this site.',
};

// Newest first, or null if the API is down
async function fetchGuestbookEntries() {
  try {
    const res = await fetch(GUESTBOOK_API, { signal: AbortSignal.timeout(2000) });
    if (res.ok) return await res.json();
  } catch (err) {
    console.error('Guestbook fetch failed:', err);
  }
  return null;
}

function entryMonth(entry) {
  const date = new Date(entry.created_at || entry.timestamp);
  return `${MONTHS[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
}

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

// Visitor text stays one plain line inside its quote: no headings, links, or HTML
function escapeMarkdown(text) {
  return String(text)
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/[\\`*_[\]<>#]/g, '\\$&');
}

// Keep in sync with renderEntry() in src/pages/guestbook.astro
function renderGuestbookEntry(entry) {
  return `
      <div style="border: 1px solid var(--dim-text); padding: 10px; margin-bottom: 10px; background: rgba(0,0,0,0.3);">
        <strong style="color: var(--link);">${escapeHtml(entry.name)}</strong>
        <span class="mono" style="font-size: 0.7rem; color: var(--dim-text);"> — ${entryMonth(entry)}</span>
        <p style="margin: 5px 0 0 0; font-size: 0.9rem;">${escapeHtml(entry.message)}</p>
      </div>
    `;
}

async function renderGuestbookEntriesMarkdown() {
  const entries = await fetchGuestbookEntries();
  if (!entries) return `Entries could not be loaded just now. Raw JSON: ${GUESTBOOK_API}`;
  if (!entries.length) return 'No entries yet.';
  return entries
    .map(
      (entry) =>
        `> **${escapeMarkdown(entry.name)}** (${entryMonth(entry)})\n> ${escapeMarkdown(entry.message)}`
    )
    .join('\n\n');
}

async function renderGuestbook(context, url) {
  const page = await context.next();
  if (!(page.headers.get('Content-Type') || '').includes('text/html')) {
    return page;
  }

  // If the API is down, leave the placeholder and let the page's JS try
  const entries = await fetchGuestbookEntries();
  let entriesHtml = null;
  if (entries) {
    entriesHtml = entries.length
      ? entries.map(renderGuestbookEntry).join('')
      : '<p class="mono" style="color: var(--dim-text); font-size: 0.8rem;">No entries yet. Be the first to sign!</p>';
  }

  const error = url.searchParams.get('error');
  const status =
    url.searchParams.get('signed') === '1'
      ? 'Signed! Thank you. Your entry is below.'
      : error && (GUESTBOOK_ERRORS[error] || 'Could not sign the guestbook. Please try again.');

  const rendered = new HTMLRewriter()
    .on('#guestbook-entries', {
      element(el) {
        if (entriesHtml) {
          el.setInnerContent(entriesHtml, { html: true });
          el.setAttribute('data-ssr', '');
        }
      },
    })
    .on('#guestbook-status', {
      element(el) {
        if (status) {
          el.setInnerContent(status);
          el.removeAttribute('hidden');
        }
      },
    })
    .transform(page);

  // The body now changes per request, so the static asset's validators no longer apply
  const headers = new Headers(rendered.headers);
  headers.delete('ETag');
  headers.delete('Last-Modified');
  headers.set('Cache-Control', 'no-cache');
  return new Response(rendered.body, { status: rendered.status, headers });
}

export async function onRequest(context) {
  const url = new URL(context.request.url);

  const markdownPage = markdownPageFor(context.request, url);
  if (markdownPage) {
    return serveMarkdown(markdownPage);
  }

  // Normal HTML site (the guestbook gets its entries rendered in)
  const path = normalizePath(url.pathname);
  const response =
    path === '/guestbook' ? await renderGuestbook(context, url) : await context.next();
  return path in MARKDOWN ? withMarkdownHeaders(response, path) : response;
}
